#nullable enable // autogenerated  

using System.Collections.Generic;
using MVZ2.GameContent.Buffs.Contraptions;
using MVZ2.GameContent.Detections;
using MVZ2.GameContent.Projectiles;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Contraptions;
using MVZ2.Vanilla.Detections;
using MVZ2.Vanilla.Enemies;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Projectiles;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Entities;
using PVZEngine;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Modifiers;
using Tools;
using UnityEngine;

namespace MVZ2.GameContent.Contraptions
{
    [AutoEntityBehaviourDefinition(VanillaContraptionNames.EXPANDispenser_Pistenser)]
    public class EXPANDispenser_Pistenser : EXPANDispenser
    {
        public EXPANDispenser_Pistenser(string nsp, string name) : base(nsp, name)
        {
            // 活塞伸长：把伸长高度加到发射偏移与碰撞体尺寸上，并在伸长时阻挡跳跃。  
            AddModifier(new Vector3Modifier(VanillaEntityProps.SHOT_OFFSET, NumberOperator.Add, PROP_EXTEND_SHOOT_OFFSET));
            AddModifier(new Vector3Modifier(EngineEntityProps.SIZE, NumberOperator.Add, PROP_EXTEND_SHOOT_OFFSET));
            AddModifier(new BooleanModifier(VanillaContraptionProps.BLOCKS_JUMP, PROP_BLOCKS_JUMP));

            // 射速等级加成：每级缩短攻击间隔（参照超级狙击发射器）
            AddModifier(new FloatModifier(VanillaEntityProps.ATTACK_SPEED, NumberOperator.AddMultiple, PROP_ATTACK_SPEED_ADDITION));

            // 大招专用：跨行探测（普攻用的 detector 只打本行）。  
            crossLaneDetector = new DispenserDetector()
            {
                ignoreHighEnemy = false,
                ignoreLowEnemy = false,
                innerLaneExpansion = 1,
                outerLaneExpansion = 1,
            };
        }

        public override void Init(Entity entity)
        {
            base.Init(entity);
            SetHasMissileBox(entity, false);          // 本融合体不使用导弹盒  
            SetTriggerTimer(entity, new FrameTimer(0)); // 初始为0=已过期，可立即触发  
        }

        // 普攻探测器：普通 DispenserDetector => 只打本行，但能探到本行高空（配合伸长命中）。  
        protected override Detector GetDetector()
        {
            return new DispenserDetector();
        }

        protected override void UpdateAI(Entity entity)
        {
            // 注意：不要调用 base.UpdateAI，否则会触发父类的导弹盒/箭矢连发/大招逻辑。  
            var triggerTimer = GetTriggerTimer(entity);
            triggerTimer?.Run(entity.GetAttackSpeed());

            if (!entity.IsEvoked())
            {
                ExtendUpdate(entity); // 活塞伸长脖子，去够本行的空中敌人  
                ShootTick(entity);    // 命中目标时会调用下面的 OnShootTick 设置点数预算  

                int remaining = GetRepeatCount(entity);
                if (remaining > 0)
                {
                    var repeatTimer = GetRepeatTimer(entity);
                    if (repeatTimer != null && repeatTimer.RunToExpired(entity.GetAttackSpeed()))
                    {
                        bool forceRocket = IsTriggerActive(entity);
                        bool fireRocket =
                            forceRocket ||
                            (remaining >= ROCKET_POINTS && entity.RNG.Next(3) == 0); // 约1/3概率小导弹  

                        FirePointProjectile(entity, fireRocket);
                        SetRepeatCount(entity, remaining - (fireRocket ? ROCKET_POINTS : SPIKE_POINTS));
                        repeatTimer.Reset();
                    }
                }
            }
            else
            {
                EvokedUpdateCustom(entity);
            }
        }

        protected override void UpdateLogic(Entity entity)
        {
            base.UpdateLogic(entity);
            // 同步活塞伸长状态到动画与属性。  
            var extend = GetExtend(entity);
            entity.SetAnimationFloat("Extend", extend);
            entity.SetProperty(PROP_EXTEND_SHOOT_OFFSET, Vector3.up * extend);
            entity.SetProperty(PROP_BLOCKS_JUMP, extend > 0);
            // 应用通用射速等级加成（换枪时由活塞发射器继承）
            entity.SetProperty(PROP_ATTACK_SPEED_ADDITION, Seeds.HeavyWeaponUpgradeUtils.GetRapidLevel(entity) * Seeds.HeavyWeaponUpgradeUtils.ATTACK_SPEED_PER_RAPID_LEVEL);
        }

        public override void OnShootTick(Entity entity)
        {
            // 触发生效中：预算9点 => 全部小导弹(3点) = 恰好3发  
            // 普通状态：预算8点，尖刺(1点)/小导弹(3点)混发  
            int points = IsTriggerActive(entity) ? TRIGGER_ROCKET_COUNT * ROCKET_POINTS : SHOOT_POINTS;
            SetRepeatCount(entity, points);

            var repeatTimer = GetRepeatTimer(entity);
            if (repeatTimer != null)
            {
                repeatTimer.ResetTime(SHOT_INTERVAL);
                repeatTimer.Frame = 0;
            }
        }

        // ================= 活塞伸长（照搬 Pistenser 逻辑）=================  
        private void ExtendUpdate(Entity pistenser)
        {
            if (pistenser.IsTimeInterval(DETECT_INTERVAL))
            {
                // 只在本行范围内找最高的敌人（detector 是本行探测器）  
                var collider = detector.DetectWithTheMost(pistenser, e => e.Entity.GetRelativeY());
                SetExtendTarget(pistenser, collider?.Entity);
            }

            var target = GetExtendTarget(pistenser);
            if (target != null && target.Position.y > pistenser.Position.y + BASE_SHOT_HEIGHT)
            {
                float targetExtend = target.GetCenter().y - (pistenser.Position.y + BASE_SHOT_HEIGHT);
                var extend = GetExtend(pistenser);
                if (Mathf.Abs(targetExtend - extend) >= 10)
                {
                    ExtendToTargetHeight(pistenser, targetExtend);
                }
            }
            else
            {
                ExtendToTargetHeight(pistenser, 0);
            }
        }

        private void ExtendToTargetHeight(Entity pistenser, float targetHeight)
        {
            var direction = GetExtendDirection(pistenser);
            float height = GetExtend(pistenser);
            if (targetHeight > height)
            {
                if (direction != 1)
                {
                    pistenser.PlaySound(VanillaSoundID.pistonOut);
                    direction = 1;
                }
            }
            else if (targetHeight < height)
            {
                if (direction != -1)
                {
                    pistenser.PlaySound(VanillaSoundID.pistonIn);
                    direction = -1;
                }
            }
            else
            {
                direction = 0;
            }
            SetExtendDirection(pistenser, direction);

            float nextHeight = height + EXTEND_SPEED * direction;
            if ((targetHeight - nextHeight) * direction < 0)
                height = targetHeight;
            else
                height = nextHeight;

            height = Mathf.Max(0, height);
            SetExtend(pistenser, height);
        }

        // ================= 触发 =================  
        public override bool CanTrigger(Entity entity)
        {
            if (IsTriggerActive(entity))
                return false;
            return base.CanTrigger(entity);
        }

        protected override void OnTrigger(Entity entity)
        {
            base.OnTrigger(entity);
            SetHasMissileBox(entity, false); // 清掉父类设置的导弹盒  

            var triggerTimer = GetTriggerTimer(entity);
            triggerTimer?.ResetTime(TRIGGER_DURATION);

            entity.PlaySound(VanillaSoundID.gunReload);
            entity.PlaySound(VanillaSoundID.powerUp);
        }

        // ================= 大招 =================  
        protected override void OnEvoke(Entity entity)
        {
            base.OnEvoke(entity);
            SetHasMissileBox(entity, false); // 清掉父类设置的导弹盒  
        }

        private void EvokedUpdateCustom(Entity entity)
        {
            var evocationTimer = GetEvocationTimer(entity);
            if (evocationTimer == null)
                return;
            evocationTimer.Run();

            if (evocationTimer.PassedInterval(EVOKE_FIRE_INTERVAL))
            {
                FireTrackingMissiles(entity, EVOKE_MISSILE_COUNT);
            }

            if (evocationTimer.Expired)
            {
                entity.SetEvoked(false);
                var shootTimer = GetShootTimer(entity);
                shootTimer?.Reset();
            }
        }

        // ================= 发射逻辑 =================  

        // 普攻单发：只打本行直线；靠活塞伸长命中本行空中敌人（不做方向重定向、不跨行）。  
        private Entity? FirePointProjectile(Entity entity, bool isRocket)
        {
            var param = entity.GetShootParams();
            if (isRocket)
            {
                param.projectileID = VanillaProjectileID.SmallRocket;
                param.damage = entity.GetDamage() * ROCKET_DAMAGE_MULT;
                param.soundID = VanillaSoundID.launch;
            }
            else
            {
                param.projectileID = entity.GetProjectileID() ?? VanillaProjectileID.AndesiteAlloySpike;
                param.damage = entity.GetDamage() * SPIKE_DAMAGE_MULT;
            }

            // 对空特攻：当脖子正伸长去够一个飞行敌人时，本次伤害加成。  
            var extendTarget = GetExtendTarget(entity);
            if (extendTarget != null && extendTarget.Exists() && extendTarget.Definition.IsFlyingEnemy())
            {
                param.damage *= AIR_DAMAGE_MULT;
            }

            SetGatlinAlt(entity, !IsGatlinAlt(entity));
            entity.TriggerAnimation("Shoot");
            return entity.ShootProjectile(param); // 使用默认水平速度，从（已伸长的）发射点射出  
        }

        // 大招：跨行发射多发追踪敌人的小导弹（优先对空、对空特攻）。  
        private void FireTrackingMissiles(Entity entity, int count)
        {
            missileBuffer.Clear();
            crossLaneDetector.DetectEntities(entity, missileBuffer); // 跨行探测  
            if (missileBuffer.Count == 0)
                return;

            var shootPoint = entity.GetShootPoint();
            missileBuffer.Sort((a, b) =>
            {
                int fa = a.Definition.IsFlyingEnemy() ? 0 : 1;
                int fb = b.Definition.IsFlyingEnemy() ? 0 : 1;
                if (fa != fb)
                    return fa - fb;
                float da = (a.GetCenter() - shootPoint).sqrMagnitude;
                float db = (b.GetCenter() - shootPoint).sqrMagnitude;
                return da.CompareTo(db);
            });

            for (int i = 0; i < count; i++)
            {
                var target = missileBuffer[i % missileBuffer.Count];
                if (target == null || !target.Exists())
                    continue;
                FireMissileAt(entity, target);
            }
        }

        private void FireMissileAt(Entity entity, Entity target)
        {
            var direction = (target.GetCenter() - entity.GetShootPoint()).normalized;
            var speed = entity.GetShotVelocity().magnitude;

            var param = entity.GetShootParams();
            param.projectileID = VanillaProjectileID.SmallRocket;
            param.damage = entity.GetDamage() * ROCKET_DAMAGE_MULT;
            if (target.Definition.IsFlyingEnemy())
                param.damage *= AIR_DAMAGE_MULT; // 对空特攻  
            param.velocity = direction * speed;

            entity.TriggerAnimation("Shoot");
            var rocket = entity.ShootProjectile(param);
            if (rocket != null)
                rocket.Target = target; // 记录目标（若小导弹支持自动跟踪即生效）  
            entity.PlaySound(VanillaSoundID.launch);
        }

        private bool IsTriggerActive(Entity entity)
        {
            var t = GetTriggerTimer(entity);
            return t != null && !t.Expired;
        }

        // ================= 新增属性 =================  
        public static FrameTimer? GetTriggerTimer(Entity entity) => entity.GetBehaviourField<FrameTimer>(PROP_TRIGGER_TIMER);
        public static void SetTriggerTimer(Entity entity, FrameTimer timer) => entity.SetBehaviourField(PROP_TRIGGER_TIMER, timer);

        public static float GetExtend(Entity entity) => entity.GetBehaviourField<float>(PROP_EXTEND);
        public static void SetExtend(Entity entity, float value) => entity.SetBehaviourField(PROP_EXTEND, value);
        public static int GetExtendDirection(Entity entity) => entity.GetBehaviourField<int>(PROP_EXTEND_DIRECTION);
        public static void SetExtendDirection(Entity entity, int value) => entity.SetBehaviourField(PROP_EXTEND_DIRECTION, value);
        public static Entity? GetExtendTarget(Entity entity)
        {
            var id = entity.GetBehaviourField<EntityID>(PROP_EXTEND_TARGET);
            return id?.GetEntity(entity.Level);
        }
        public static void SetExtendTarget(Entity entity, Entity? value) => entity.SetBehaviourField(PROP_EXTEND_TARGET, new EntityID(value));

        // ================= 常量（可自行调数值）=================  
        public const int SHOOT_POINTS = 7;          // 普通攻击总点数  
        public const int SPIKE_POINTS = 1;          // 尖刺占用点数  
        public const int ROCKET_POINTS = 3;         // 小导弹占用点数  
        public const int SHOT_INTERVAL = 3;         // 单发之间的帧间隔  

        public const int TRIGGER_DURATION = 300;    // 触发限时持续帧数  
        public const int TRIGGER_ROCKET_COUNT = 3;  // 触发期间每次攻击的小导弹数  

        public const int EVOKE_FIRE_INTERVAL = 10;  // 大招期间发射间隔帧数  
        public const int EVOKE_MISSILE_COUNT = 5;   // 大招每波小导弹数  

        public const float SPIKE_DAMAGE_MULT = 1f;  // 尖刺伤害倍率  
        public const float ROCKET_DAMAGE_MULT = 1.5f; // 小导弹伤害倍率  
        public const float AIR_DAMAGE_MULT = 1f;    // 对空特攻额外倍率  

        // 活塞伸长参数（照搬 Pistenser）  
        public const float BASE_SHOT_HEIGHT = 30;
        public const float EXTEND_SPEED = 10;
        public const int DETECT_INTERVAL = 8;

        private readonly Detector crossLaneDetector;
        private readonly List<Entity> missileBuffer = new List<Entity>();

        public static readonly VanillaEntityPropertyMeta<FrameTimer> PROP_TRIGGER_TIMER = new VanillaEntityPropertyMeta<FrameTimer>("PistenserTriggerTimer");
        public static readonly VanillaEntityPropertyMeta<float> PROP_EXTEND = new VanillaEntityPropertyMeta<float>("Extend");
        public static readonly VanillaEntityPropertyMeta<Vector3> PROP_EXTEND_SHOOT_OFFSET = new VanillaEntityPropertyMeta<Vector3>("ExtendShootOffset");
        public static readonly VanillaEntityPropertyMeta<bool> PROP_BLOCKS_JUMP = new VanillaEntityPropertyMeta<bool>("BlocksJump");
        public static readonly VanillaEntityPropertyMeta<int> PROP_EXTEND_DIRECTION = new VanillaEntityPropertyMeta<int>("ExtendDirection");
        public static readonly VanillaEntityPropertyMeta<EntityID> PROP_EXTEND_TARGET = new VanillaEntityPropertyMeta<EntityID>("ExtendTarget");
        public static readonly VanillaEntityPropertyMeta<float> PROP_ATTACK_SPEED_ADDITION = new VanillaEntityPropertyMeta<float>("attack_speed_addition");
    }
}
